export const taskOutputsContract = <ThrowOnError extends boolean = false>(options: Options<TaskOutputsContractData, ThrowOnError>): RequestResult<TaskOutputsContractResponses, TaskOutputsContractErrors, ThrowOnError> => (options.client ?? client).get<TaskOutputsContractResponses, TaskOutputsContractErrors, ThrowOnError>({
    security: [{
            key: 'taskBearer',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/v1/tasks/{taskUid}/outputs',
    ...options
});
